INSERT INTO `tag` (`name`, `status`) SELECT 'SEO', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'SEO');
INSERT INTO `tag` (`name`, `status`) SELECT 'Generative AI', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Generative AI');
INSERT INTO `tag` (`name`, `status`) SELECT 'Digital Marketing', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Digital Marketing');
INSERT INTO `tag` (`name`, `status`) SELECT 'Prompt Engineering', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'Prompt Engineering');
INSERT INTO `tag` (`name`, `status`) SELECT 'LinkedIn Marketing', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'LinkedIn Marketing');
INSERT INTO `tag` (`name`, `status`) SELECT 'WSQ', 1 FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `tag` WHERE `name` = 'WSQ');

SET @post_id := (SELECT `post_id` FROM `mmd_blog_post` WHERE `url_key` = 'ai-prompts-seo-meta-linkedin-posts');

